The evidence points to one root cause in ts-station-service, with the impact travelling up the call chain to the user-facing dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-station-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "log",
          "sql": "SELECT service_name, level, substr(message,1,160) msg, count(*) c FROM abnormal_logs WHERE service_name='ts-station-service' AND level='ERROR' GROUP BY 1,2,3 ORDER BY c DESC",
          "claim": "Station logs ERROR 'Communications link failure' and Hikari 'Connection is not available, request timed out after 30000ms' about 26 times."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-station-service' AND span_name IN ('SELECT station','StationRepository.findByNames','StationController.queryForIdBatch') GROUP BY ALL ORDER BY 1,2",
          "claim": "Station's own DB spans fail with Error status at about 30 s p95, versus about 1 ms in normal operation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-station-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT * FROM abnormal_traces) SELECT c.service_name callee, pp.service_name caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, round(quantile_cont(c.duration,0.95)/1e6,1) c_p95 FROM t c JOIN t pp ON c.parent_span_id=pp.span_id AND c.trace_id=pp.trace_id WHERE c.service_name='ts-station-service' AND pp.service_name='ts-basic-service' GROUP BY ALL",
          "claim": "Basic-service calls to station fail with Error status and about 30 s p95 latency."
        }
      ]
    },
    {
      "from": "ts-station-service",
      "to": "ts-admin-basic-info-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT * FROM abnormal_traces) SELECT c.service_name callee, pp.service_name caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM t c JOIN t pp ON c.parent_span_id=pp.span_id AND c.trace_id=pp.trace_id WHERE c.service_name='ts-station-service' AND pp.service_name='ts-admin-basic-info-service' GROUP BY ALL",
          "claim": "Admin-basic-info calls to station return Error status with about 30 s latency."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT * FROM abnormal_traces) SELECT c.service_name callee, pp.service_name caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, round(quantile_cont(c.duration,0.95)/1e6,1) c_p95 FROM t c JOIN t pp ON c.parent_span_id=pp.span_id AND c.trace_id=pp.trace_id WHERE c.service_name='ts-basic-service' AND pp.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "Travel-service calls to basic-service fail with Error status at about 30 s p95."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT * FROM abnormal_traces) SELECT c.service_name callee, pp.service_name caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, round(quantile_cont(c.duration,0.95)/1e6,1) c_p95 FROM t c JOIN t pp ON c.parent_span_id=pp.span_id AND c.trace_id=pp.trace_id WHERE c.service_name='ts-travel-service' AND pp.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "Route-plan calls to travel-service fail with Error status, about 30 s p95 latency."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-route-plan-service') AND span_name='POST' GROUP BY ALL ORDER BY 1,2",
          "claim": "Route-plan and travel-plan POST spans show Error status with about 30 s p95 latency in the incident window."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT * FROM abnormal_traces) SELECT c.service_name callee, pp.service_name caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM t c JOIN t pp ON c.parent_span_id=pp.span_id AND c.trace_id=pp.trace_id WHERE c.service_name='ts-travel-service' AND pp.service_name='ts-ui-dashboard' GROUP BY ALL",
          "claim": "Dashboard calls to travel-service fail with Error status, about 30 s latency, in the incident window."
